import {loadApu,searchApu,apuSnapshot} from './apu-model.mjs';
export function mountApuPicker(form,{initial=null,onChange}={}){
 let selection=structuredClone(initial),catalog=null,ticket=0;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const host=document.createElement('section');host.className='lpApuPicker';form.querySelector('[data-step="0"]').append(host);
 function summary(){host.innerHTML=`<h4>Partida y operación APU</h4>${selection?`<p><b>APU ${esc(selection.code)}</b> · ${esc(selection.operation?.label||selection.description)}</p><small>${esc(selection.version)}${selection.operation?' · Coeficiente: '+esc(selection.operation.coefficient)+' '+esc(selection.operation.resourceUnitOriginal)+' de recurso/'+esc(selection.unitOriginal):''}</small>`:'<p>Busca en el APU del proyecto o continúa con una actividad manual.</p>'}<button type="button" data-apu-open>${selection?'Cambiar APU':'Buscar partida u operación'}</button>${selection?'<button type="button" data-apu-clear>Continuar sin APU</button><details><summary>Detalle APU</summary><p>'+esc(selection.operation?.limitation||'Referencia documental de la partida. No implica rendimiento por persona validado.')+'</p></details>':''}<div data-apu-search></div>`;host.querySelector('[data-apu-open]').onclick=open;host.querySelector('[data-apu-clear]')?.addEventListener('click',()=>{selection=null;onChange(null);summary();});}
 async function open(){const target=host.querySelector('[data-apu-search]'),id=++ticket;target.innerHTML='<p role="status">Leyendo catálogo APU…</p>';try{catalog=await loadApu();if(id!==ticket||!host.isConnected)return;target.innerHTML='<label>Buscar código, descripción, especialidad u operación<input data-apu-query type="search" autocomplete="off"></label><div data-apu-results></div><div data-apu-detail></div><p role="alert"></p><button type="button" data-apu-cancel>Cerrar búsqueda</button>';const results=target.querySelector('[data-apu-results]'),query=target.querySelector('[data-apu-query]');const search=()=>{const matches=searchApu(catalog,query.value);results.innerHTML=matches.map(p=>`<button type="button" data-apu-part="${esc(p.id)}"><b>${esc(p.code)}</b> ${esc(p.description)}<small>${esc(p.unit)} · ${p.selectable?'Referencia documental':'No ejecutable: '+esc(p.issues.join(', '))}</small></button>`).join('')||'<p>Sin coincidencias. Puedes continuar manualmente.</p>';results.querySelectorAll('[data-apu-part]').forEach(b=>b.onclick=()=>detail(b.dataset.apuPart));};query.oninput=()=>{clearTimeout(query.timer);query.timer=setTimeout(search,120);};target.querySelector('[data-apu-cancel]').onclick=()=>{ticket++;summary();};search();query.focus();
 function detail(id){const p=catalog.parts.find(p=>p.id===id),el=target.querySelector('[data-apu-detail]');el.innerHTML=`<h4>${esc(p.code+' · '+p.description)}</h4><p>${esc(p.chapterPath.join(' / '))}</p><button type="button" data-use-part ${p.selectable?'':'disabled'}>Asociar partida completa</button><h4>Operaciones documentadas</h4>${p.operations.map(o=>`<button type="button" data-apu-operation="${esc(o.id)}" ${o.selectable?'':'disabled'}>${esc(o.label)}<small>${esc(o.coefficient)} ${esc(o.resourceUnitOriginal)} de recurso/${esc(p.unitOriginal)} · ${o.selectable?'Verificada en documento; composición pendiente':'Pendiente de revisión documental'}</small></button>`).join('')||'<p>Sin operaciones verificadas.</p>'}<details><summary>Recursos y trazabilidad</summary>${p.resources.map(r=>`<p>${esc(r.code)} · ${esc(r.nature)} · ${esc(r.description)} · ${esc(r.coefficientOriginal)} ${esc(r.unitOriginal)} · fila ${r.row}</p>`).join('')}</details>`;const apply=op=>{try{const next=apuSnapshot(catalog,p.id,op);if(form.elements.cantidad.value&&form.elements.unidad.value!==p.unit&&!confirm('La partida utiliza '+p.unit+'. ¿Cambiar la unidad conservando la cantidad para su revisión?'))return;const changedUnit=form.elements.unidad.value!==p.unit;selection=next;if(![...form.elements.unidad.options].some(o=>o.value===p.unit))form.elements.unidad.add(new Option(p.unit,p.unit));form.elements.unidad.value=p.unit;if(changedUnit&&form.elements.origenCantidad)form.elements.origenCantidad.value='manual';form.elements.unidad.dispatchEvent(new Event('change',{bubbles:true}));if(!form.elements.actividad.value.trim())form.elements.actividad.value=next.operation?.label||p.description;if(!form.elements.especialidad.value.trim())form.elements.especialidad.value=p.chapterPath[0]||'';onChange(next);summary();form.dispatchEvent(new Event('input',{bubbles:true}));}catch(e){target.querySelector('[role=alert]').textContent=e.message;}};el.querySelector('[data-use-part]').onclick=()=>apply(null);el.querySelectorAll('[data-apu-operation]').forEach(b=>b.onclick=()=>apply(b.dataset.apuOperation));el.scrollIntoView({block:'nearest'});}
 }catch(e){target.innerHTML='<p role="alert">'+esc(e.message)+'</p>';}}
 summary();return {read:()=>structuredClone(selection)};
}
